// Take all RSS items, pick most recent N stories, format for Claude
const MAX_STORIES = 20;
const items = $input.first().json.data || [];

// Sort by pubDate descending, take top MAX_STORIES
const sorted = items
  .filter(i => i.title && i.link)
  .sort((a, b) => new Date(b.pubDate || 0) - new Date(a.pubDate || 0))
  .slice(0, MAX_STORIES);

const articleList = sorted.map((item, i) => 
  `${i + 1}. TITLE: ${item.title}\n   URL: ${item.link}\n   DATE: ${item.pubDate || 'Unknown'}\n   SUMMARY: ${(item.contentSnippet || item.content || '').substring(0, 200)}`
).join('\n\n');

return [{ json: { article_list: articleList, total_fetched: sorted.length } }];

