const raw = $input.first().json.content[0].text;
let digest;
try {
  digest = JSON.parse(raw);
} catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  try { digest = JSON.parse(m[0]); } catch { digest = { newsletter_title: 'Weekly Digest', intro_paragraph: '', stories: [], closing_thought: '', email_subject_lines: [] }; }
}

// Build plain-text newsletter
const stories = (digest.stories || []).map(s => 
  `${s.rank}. ${s.title}\n${s.url}\n→ ${s.why_it_matters}\nTakeaway: ${s.key_takeaway}`
).join('\n\n');

const plainText = `${digest.newsletter_title}\n\n${digest.intro_paragraph}\n\n${stories}\n\n${digest.closing_thought}`;

return [{ json: { ...digest, plain_text: plainText, generated_at: new Date().toISOString() } }];

